parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "critica": {
      "type": "string",
      "description": "Instrucción breve para el asistente: qué está mal y cómo corregirlo. Si está aceptado, una frase que diga por qué."
    },
    "categoria_error": {
      "type": "string",
      "enum": [
        "NINGUNO",
        "DATO_INVENTADO",
        "CONTRADICE_CONTEXTO",
        "PROMESA_NO_AUTORIZADA",
        "DATO_SENSIBLE",
        "RESPUESTA_INCOMPLETA",
        "NO_RESPONDE_LA_CONSULTA",
        "NO_SE_INCORRECTO",
        "TONO_O_FORMATO"
      ]
    },
    "exactitud_factual": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5
    },
    "estado_veredicto": {
      "type": "string",
      "enum": ["ACEPTADO", "CORREGIR", "RECHAZADO"]
    }
  },
  "required": ["critica", "categoria_error", "exactitud_factual", "estado_veredicto"],
  "additionalProperties": false
}

parameters.jsCode:
// EL JUEZ PONE LA NOTA; EL CÓDIGO HACE CUMPLIR LA POLÍTICA (auditable y sin LLM).
// Modo: Run Once for Each Item
const p = $('Payload para el Juez').all(0, $runIndex)[0].json; // lo que vio el Juez (misma vuelta del loop)
const v = $json.output ?? {};                  // lo que devolvió el Juez (vacío si el Juez falló)
const ORDEN = { ACEPTADO: 0, CORREGIR: 1, RECHAZADO: 2 };
const CAT_RECHAZO = ['DATO_INVENTADO', 'CONTRADICE_CONTEXTO', 'PROMESA_NO_AUTORIZADA', 'DATO_SENSIBLE'];
const CAT_CORREGIR = ['RESPUESTA_INCOMPLETA', 'NO_RESPONDE_LA_CONSULTA', 'NO_SE_INCORRECTO', 'TONO_O_FORMATO'];

const score = Number.isInteger(v.exactitud_factual) ? v.exactitud_factual : null;
const estadoLlm = v.estado_veredicto in ORDEN ? v.estado_veredicto : null;
const base = {
  ...p,
  id_evaluacion: `${p.execution_id}-${p.intento}`,
  timestamp: new Date().toISOString(),
  exactitud_factual: score,
  estado_veredicto_llm: estadoLlm,
  critica: v.critica ?? '',
};

// 1) Falla cerrada: veredicto ilegible o fuera de rango → decide una persona.
if (score === null || score < 1 || score > 5 || estadoLlm === null) {
  return { json: { ...base, estado_veredicto: 'RECHAZADO', categoria_error: 'ERROR_JUEZ',
    motivo_codigo: 'veredicto inválido del Juez → revisión humana' } };
}

// 2) Piso por nota (umbral de la consigna: ACEPTADO solo con exactitud >= 4).
const porNota = score >= 4 ? 'ACEPTADO' : score === 3 ? 'CORREGIR' : 'RECHAZADO';

// 3) Piso por categoría.
const cat = v.categoria_error;
const porCategoria = CAT_RECHAZO.includes(cat) ? 'RECHAZADO' : CAT_CORREGIR.includes(cat) ? 'CORREGIR' : 'ACEPTADO';

// 4) Regla dura: promesas de plata o de plazos que no figuran en el contexto.
const texto = String(p.respuesta_agente || '');
const ctx = (String(p.contexto_rag || '') + ' ' + String(p.contexto_memoria || '')).toLowerCase();
const PROMESAS = /(reembols\w*|reintegr\w*|te devolvemos|devoluci[oó]n|descuento|bonificaci[oó]n|bonificamos|sin cargo|cr[eé]dito a favor|en (las pr[oó]ximas )?\d+ ?(h|hs|horas|d[ií]as h[aá]biles)\b|hoy mismo)/gi;
const hallazgos = (texto.match(PROMESAS) || []).filter(m => !ctx.includes(m.toLowerCase()));

// El estado final es el MÁS SEVERO entre lo que dijo el Juez, la nota, la categoría y la regla dura.
let estado = [estadoLlm, porNota, porCategoria].reduce((a, b) => (ORDEN[b] > ORDEN[a] ? b : a));
const motivos = [];
if (hallazgos.length) {
  estado = 'RECHAZADO';
  motivos.push(`regla dura: promesa no autorizada (${[...new Set(hallazgos)].join(', ')})`);
}
// Regla de tono (calibración ejecución 437: el Juez aceptó 'Toca "Refrescar Estado MP"'): tuteo → como mínimo CORREGIR.
const TUTEO = /\b(puedes|tienes|necesitas|quieres|debes|asegúrate|fíjate|contáctanos|escríbenos)\b|(^|[.:;!?]\s+|\n)(Toca|Revisa|Verifica|Intenta|Ingresa|Selecciona|Confirma|Haz|Abre|Cierra|Recuerda|Pide)\b/;
if (TUTEO.test(texto) && ORDEN[estado] < ORDEN.CORREGIR) {
  estado = 'CORREGIR';
  motivos.push('regla de tono: tuteo detectado');
}
if (estado !== estadoLlm) motivos.push(`el código endureció ${estadoLlm} → ${estado}`);

return { json: {
  ...base,
  estado_veredicto: estado,
  categoria_error: hallazgos.length && cat === 'NINGUNO' ? 'PROMESA_NO_AUTORIZADA' : (motivos.some(m => m.startsWith('regla de tono')) && cat === 'NINGUNO' ? 'TONO_O_FORMATO' : cat),
  motivo_codigo: motivos.join(' · '),
} };

const e = $json;
const feedback =
  `TU RESPUESTA ANTERIOR FUE OBSERVADA POR EL SUPERVISOR DE CALIDAD ` +
  `(exactitud ${e.exactitud_factual}/5, ${e.categoria_error}).\n` +
  `Corregí esto y no cambies lo que estaba bien:\n${e.motivo_codigo ? 'Motivo detectado por el control automático: ' + e.motivo_codigo + '. Escribí en español rioplatense con voseo (tocá, revisá, podés).\n' : ''}${e.critica}\n` +
  `Usá solo la información del manual y de la memoria del cliente. No agregues datos nuevos.`;
return [{ json: { ...e, feedback_juez: feedback, intento: Number(e.intento || 0) + 1 } }];

// Vuelve al Juez con la respuesta corregida (misma vuelta del loop)
const prev = $('Preparar reintento').all(0, $runIndex)[0].json;
const r = $input.first().json;
const frag = Array.isArray(r.fragmentos) && r.fragmentos.length ? r.fragmentos.map(f => `[Sección ${f.seccion} · score ${f.score}] ${f.contenido}`).join('\n\n') : prev.contexto_rag;
return [{ json: { ...prev, respuesta_agente: r.respuesta ?? '', requires_human: Boolean(r.requires_human), contexto_rag: frag } }];

const p = $('Preparar alerta HITL').last().json;
const t = String($json.data?.text ?? '').trim();
return [{ json: { ...p, decision_humana: t ? 'EDITADO_HUMANO' : 'SIN_RESPUESTA', liberar: Boolean(t), respuesta_final: t } }];
